helper = '''function urlBase64ToUint8Array(base64String) {\n  const padding = "=".repeat((4 - (base64String.length % 4)) % 4);\n  const base64 = (base64String + padding).replace(/-/g, "+").replace(/_/g, "/");\n  return Uint8Array.from(window.atob(base64), (c) => c.charCodeAt(0));\n}\n\nfunction PushNotifications({ user }) {\n  const [state, setState] = useState("idle");\n  const supported = typeof window !== "undefined" && "serviceWorker" in navigator && "PushManager" in window && "Notification" in window;\n  const enable = async () => {\n    if (!supported) { setState("unsupported"); return; }\n    try {\n      setState("loading");\n      const permission = await Notification.requestPermission();\n      if (permission !== "granted") { setState("denied"); return; }\n      const registration = await navigator.serviceWorker.ready;\n      let subscription = await registration.pushManager.getSubscription();\n      if (!subscription) subscription = await registration.pushManager.subscribe({ userVisibleOnly: true, applicationServerKey: urlBase64ToUint8Array(VAPID_PUBLIC_KEY) });\n      const json = subscription.toJSON();\n      const { error } = await supabase.from("push_subscriptions").upsert({ user_id: user.id, endpoint: json.endpoint, p256dh: json.keys?.p256dh || "", auth: json.keys?.auth || "", user_agent: navigator.userAgent, updated_at: new Date().toISOString() }, { onConflict: "user_id,endpoint" });\n      if (error) throw error;\n      setState("enabled");\n    } catch (e) { console.error(e); setState("error"); }\n  };\n  return <button className="btn btn-ghost" onClick={enable} disabled={state === "loading" || state === "enabled"}><Bell size={15} /> {state === "enabled" ? "الإشعارات مفعّلة" : state === "loading" ? "جارٍ التفعيل..." : "تفعيل الإشعارات"}</button>;\n}\n\nfunction AnnouncementFeed({ announcements, role }) {\n  const visible = (announcements || []).filter(a => a.target_role === "all" || a.target_role === role);\n  if (!visible.length) return null;\n  return <section className="announcement-feed"><div className="section-head"><div><div className="section-kicker"><Megaphone size={15} /> إعلانات المعهد</div><h3>آخر الإعلانات</h3></div></div><div className="announcement-list">{visible.map(a => <article className="announcement-card" key={a.id}><div className="announcement-icon"><Megaphone size={18} /></div><div><h4>{a.title}</h4><p>{a.body}</p><small>{new Date(a.created_at).toLocaleDateString("ar-EG")}</small></div></article>)}</div></section>;\n}\n\n''' + needle
