sw = Path('public/sw.js') if Path('public/sw.js').exists() else Path('sw.js')
if sw.exists():
    w = sw.read_text()
    if 'self.addEventListener("push"' not in w:
        w += '''\n\nself.addEventListener("push", (event) => {\n  let data = {};\n  try { data = event.data ? event.data.json() : {}; } catch { data = { body: event.data?.text() || "" }; }\n  event.waitUntil(self.registration.showNotification(data.title || "معهد البر", { body: data.body || "لديك إشعار جديد من معهد البر.", icon: "/icons/icon-192.png", badge: "/icons/icon-192.png", dir: "rtl", lang: "ar", data: { url: data.url || "/" } }));\n});\n\nself.addEventListener("notificationclick", (event) => {\n  event.notification.close();\n  const url = event.notification.data?.url || "/";\n  event.waitUntil(clients.matchAll({ type: "window", includeUncontrolled: true }).then((list) => { const existing = list.find((client) => "focus" in client); if (existing) { existing.navigate(url); return existing.focus(); } return clients.openWindow(url); }));\n});\n'''
        sw.write_text(w)
else:
    raise SystemExit('service worker not found')
